"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["53469"],{7944(e){e.exports=JSON.parse('{"id":"F406","slug":"fd-explicit-step","name":"Finite Difference: Explicit Scheme Step and Stability","subject":"Quantitative Finance","section":"Quant","topic":"Finite difference methods","level":"Intermediate","aliases":["finite difference methods","heat equation","explicit scheme","numerical PDE","CFL condition"],"formula":{"latex":"u_{i}^{n+1}=u_{i}^{n}+\\\\alpha\\\\left(u_{i+1}^{n}-2u_{i}^{n}+u_{i-1}^{n}\\\\right),\\\\quad \\\\alpha=\\\\frac{D\\\\,\\\\Delta t}{(\\\\Delta x)^{2}}\\\\le\\\\tfrac{1}{2}","also":[],"text":"New value at a grid point = Old value + alpha x (Value on the right - 2 x Old value + Value on the left), with alpha = D x time step / (grid spacing)^2; the scheme is stable only if alpha <= 0.5"},"symbols":[{"symbol":"u","meaning":"Value at a grid point (option value or temperature)","unit":"number"},{"symbol":"D","meaning":"Diffusion coefficient. For Black-Scholes in log price it is sigma^2 / 2","unit":"number"},{"symbol":"Delta t, Delta x","meaning":"Time step and grid spacing","unit":"numbers"},{"symbol":"alpha","meaning":"Mesh ratio. Above 0.5 the explicit scheme blows up","unit":"number"}],"when_to_use":"Use it to solve a pricing equation on a grid by stepping forward in time. Each point moves toward the average of its neighbors, which is the discrete form of the second derivative. The explicit scheme is simple but requires small time steps for stability. Implicit and Crank-Nicolson schemes remove that limit.","worked_example":{"problem":"In a grid, one point has a value of 10.0 with neighbors 8.0 and 13.0. The diffusion coefficient is 0.02, the time step 0.01 and the grid spacing 0.1. Find the next value and test the stability. Then try a time step of 0.05.","inputs":{"u":10,"ul":8,"ur":13,"dd":0.02,"dt":0.01,"dx":0.1,"dt2":0.05},"steps":[{"label":"alpha = D x dt / dx^2","working":"0.02 x 0.01 / 0.1^2","value":"0.0200"},{"label":"Stable? (1 = yes, 0 = no)","working":"1 if 0.02<=0.5 else 0","value":"1"},{"label":"New value = u + alpha x (right - 2u + left)","working":"10+0.02 x (13-2 x 10+8)","value":"10.0200"},{"label":"alpha with the larger time step","working":"0.02 x 0.05 / 0.1^2","value":"0.1000"}],"answer":"The mesh ratio is 0.0200, within the stable limit of 0.5, and the new value is 10.0200. With a time step of 0.05 the ratio would be 0.1000, which is above 0.5, so the explicit scheme would be unstable."},"calculator":{"available":true,"inputs":[{"id":"u","label":"Value at the point","unit":"","type":"number","default":10,"hint":""},{"id":"ul","label":"Value on the left","unit":"","type":"number","default":8,"hint":""},{"id":"ur","label":"Value on the right","unit":"","type":"number","default":13,"hint":""},{"id":"dd","label":"Diffusion coefficient","unit":"","type":"number","default":0.02,"hint":""},{"id":"dt","label":"Time step","unit":"","type":"number","default":0.01,"hint":""},{"id":"dx","label":"Grid spacing","unit":"","type":"number","default":0.1,"hint":""},{"id":"dt2","label":"Larger time step to test","unit":"","type":"number","default":0.05,"hint":""}],"checks":[{"expr":"dx>0 and dt>0","message":"The time step and grid spacing must be above zero."}],"steps":[{"id":"alpha","label":"alpha = D x dt / dx^2","expr":"dd*dt/dx^2","format":"num4"},{"id":"stable","label":"Stable? (1 = yes, 0 = no)","expr":"1 if alpha<=0.5 else 0","format":"num0"},{"id":"unew","label":"New value = u + alpha x (right - 2u + left)","expr":"u+alpha*(ur-2*u+ul)","format":"num4"},{"id":"alpha2","label":"alpha with the larger time step","expr":"dd*dt2/dx^2","format":"num4"}],"results":["unew","alpha"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"alpha":0.02,"stable":1,"unew":10.02,"alpha2":0.1}},"finder":{"finds":"One explicit finite difference step and whether it is stable","needs":"Neighbouring values, diffusion coefficient, steps"},"related":[{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price"},{"slug":"bs-pde-check","name":"Black-Scholes PDE Check"},{"slug":"binomial-option-two-step","name":"Binomial Option Pricing (Two Steps)"}],"related_ids":["F331","F403","F330"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msubsup><mi>u</mi><mi>i</mi><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow></msubsup><mo>=</mo><msubsup><mi>u</mi><mi>i</mi><mi>n</mi></msubsup><mo>+</mo><mi>\u03B1</mi><mrow><mo fence=\\"true\\">(</mo><msubsup><mi>u</mi><mrow><mi>i</mi><mo>+</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo>\u2212</mo><mn>2</mn><msubsup><mi>u</mi><mi>i</mi><mi>n</mi></msubsup><mo>+</mo><msubsup><mi>u</mi><mrow><mi>i</mi><mo>\u2212</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo fence=\\"true\\">)</mo></mrow><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>\u03B1</mi><mo>=</mo><mfrac><mrow><mi>D</mi><mtext>\u2009</mtext><mi mathvariant=\\"normal\\">\u0394</mi><mi>t</mi></mrow><mrow><mo stretchy=\\"false\\">(</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>x</mi><msup><mo stretchy=\\"false\\">)</mo><mn>2</mn></msup></mrow></mfrac><mo>\u2264</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">u_{i}^{n+1}=u_{i}^{n}+\\\\alpha\\\\left(u_{i+1}^{n}-2u_{i}^{n}+u_{i-1}^{n}\\\\right),\\\\quad \\\\alpha=\\\\frac{D\\\\,\\\\Delta t}{(\\\\Delta x)^{2}}\\\\le\\\\tfrac{1}{2}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"fi-number-4-percent","name":"Financial Independence Number and the 4% Rule"},"next":{"slug":"fiscal-multiplier","name":"Fiscal Multiplier"},"lesson":null,"total":522}')}}]);